     "type": "query",
     "name": "query",
     "provider": "query",
     "account": "query",
     "date": "query",
     "service": "query",
     "code": "query",
     "amount": "query",
     "state": "query",
     "reason": "query",
     "insured": "query",
     "setting": "query",
     "billed_by": "query"
